'use strict';

// MODULES //

var max = require( '@stdlib/math/base/special/max' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );


// MAIN //

/**
* Computes the hinge loss between two double-precision floating-point numbers.
*
* @param {number} t - threshold value
* @param {number} y - true target value
* @param {number} p - predicted value
* @returns {number} hinge loss
*
* @example
* var v = hinge( 1.0, 1.0, 0.782 );
* // returns ~0.218
*
* @example
* var v = hinge( 2.4, 1.0, 0.202 );
* // returns 2.198
*
* @example
* var v = hinge( 1.1, 1.0, -0.999 );
* // returns 2.099
*
* @example
* var v = hinge( 5.0, -1.0, 0.234  );
* // returns 5.234
*
* @example
* var v = hinge( 0.0, -1.0, 0.2 );
* // returns 0.2
*
* @example
* var v = hinge( 2.0, 1.0, -0.9 );
* // returns 2.9
*/
function hinge( t, y, p ) {
	if ( isnan( t ) || isnan( y ) || isnan( p ) || ( y !== -1.0 && y !== 1.0 ) ) {
		return NaN;
	}
	return max( 0.0, t - ( y*p ) );
}


// EXPORTS //

module.exports = hinge;
